"""harness-style eval の機械判定部分を採点する。

fixture-e-style と実行後 repo を比較し、
「エージェントが新しく書いた行」だけを対象に規約違反を数える。
"""
import difflib
import json
import pathlib
import re
import sys

FIXTURE = pathlib.Path(
    "/Users/1natsu/ghq/github.com/1natsu-vacation/agent-skills/"
    "eval-fixtures/document-harness/fixture-e-style"
)
DASHES = "—–―─"
JARGON = ["キューのホーム", "バックプレッシャの底", "ホーム", "アンカー", "ゲート"]
WORKLOG = re.compile(r"\d{4}-\d{2}-\d{2}\s*に|さんの依頼|改訂している|回改訂")
UNTOUCHED = ["docs/api-contract.md", "docs/incident-2026-05-payment-timeout.md"]


def md_files(root: pathlib.Path):
    return sorted(p for p in root.rglob("*.md") if ".git" not in p.parts)


def added_lines(repo: pathlib.Path):
    """新規ファイルの全行 ＋ 既存ファイルで追加・変更された行を返す。"""
    out = []
    for path in md_files(repo):
        rel = path.relative_to(repo)
        old = FIXTURE / rel
        new_text = path.read_text(encoding="utf-8").splitlines()
        if not old.exists():
            out += [(str(rel), i + 1, ln) for i, ln in enumerate(new_text)]
            continue
        old_text = old.read_text(encoding="utf-8").splitlines()
        sm = difflib.SequenceMatcher(None, old_text, new_text)
        for tag, _, _, j1, j2 in sm.get_opcodes():
            if tag in ("insert", "replace"):
                out += [(str(rel), j + 1, new_text[j]) for j in range(j1, j2)]
    return out


def in_table_or_range(line: str) -> bool:
    return line.strip().startswith("|") or re.search(r"\d\s*–\s*\d", line) is not None


def main(run_repo: str):
    repo = pathlib.Path(run_repo)
    added = added_lines(repo)
    res = {}

    dash_hits = [
        (f, n, l) for f, n, l in added
        if any(d in l for d in DASHES) and not in_table_or_range(l)
    ]
    res["no_dash_in_new_text"] = {"passed": not dash_hits, "evidence": dash_hits[:10]}

    jargon_hits = [(f, n, l) for f, n, l in added if any(j in l for j in JARGON)]
    res["no_jargon_reuse_in_new_text"] = {
        "passed": not jargon_hits,
        "evidence": jargon_hits[:10],
        "note": "『ホーム』『アンカー』『ゲート』の単純一致。是正のための引用は目視で除外する",
    }

    worklog_hits = [(f, n, l) for f, n, l in added if WORKLOG.search(l)]
    res["no_worklog_in_new_text"] = {"passed": not worklog_hits, "evidence": worklog_hits[:10]}

    touched = []
    for rel in UNTOUCHED:
        a, b = FIXTURE / rel, repo / rel
        if not b.exists() or a.read_text(encoding="utf-8") != b.read_text(encoding="utf-8"):
            touched.append(rel)
    res["out_of_scope_files_untouched"] = {"passed": not touched, "evidence": touched}

    qd = (repo / "docs/queue-design.md")
    stale = "再投入の上限は設けていない" in qd.read_text(encoding="utf-8") if qd.exists() else True
    res["stale_statement_updated"] = {"passed": not stale, "evidence": "旧記述が残存" if stale else ""}

    changed = sorted({f for f, _, _ in added})
    res["_changed_md_files"] = changed
    print(json.dumps(res, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main(sys.argv[1])

